/bin/bash -lc "python - <<'PY'
from sim import Sim
import numpy as np
for mode in ['zero','homeasctrl']:
    sim=Sim()
    for t in range(1200):
        if mode=='zero':
            sim.data.ctrl[:] = 0
        else:
            sim.data.ctrl[:] = sim.home_ctrl()
        sim.step(1)
    print(mode,'pelvis',sim.pelvis_position(),'up',sim.torso_up(),'dist',sim.distance_to_target())
